hooks.command:
command -v python3 >/dev/null 2>&1 || exit 0
[ -x "${CLAUDE_PROJECT_DIR:-.}/bin/gotdocs" ] || exit 0
python3 -c '
import json,os,subprocess,sys
try:
    root=os.environ.get("CLAUDE_PROJECT_DIR") or os.getcwd()
    exe=os.path.join(root,"bin","gotdocs")
    ev=json.load(sys.stdin)
    ti=ev.get("tool_input") or {}
    target=ti.get("file_path") or ti.get("notebook_path") or ""
    if not target: raise SystemExit(0)
    rel=os.path.relpath(os.path.abspath(target),root).replace(os.sep,"/")
    if rel.startswith(".."): raise SystemExit(0)
    raw=subprocess.run([exe,"impacted",rel,"--json"],cwd=root,stdout=subprocess.PIPE,stderr=subprocess.DEVNULL,timeout=10).stdout
    data=json.loads(raw.decode("utf-8","replace") or "{}")
    seen=[]; decisions=[]
    for entry in data.get("paths") or []:
        if entry.get("ignored"): continue
        for doc in entry.get("docs") or []:
            item=str(doc.get("doc_id"))+" ("+str(doc.get("path"))+")"
            if str(doc.get("path","")).startswith("decisions/"):
                if item not in decisions: decisions.append(item)
                continue
            if item not in seen: seen.append(item)
    if not seen and not decisions: raise SystemExit(0)
    parts=[]
    if seen:
        parts.append("gotdocs: "+rel+" is covered by "+str(len(seen))+" doc(s): "+"; ".join(seen)
            +". Decide per doc, in this session, whether the documented behavior changed."
            +" If it changed: edit the doc, set updated: to today, then run bin/gotdocs index."
            +" If it did not: run bin/gotdocs verify <doc-id> and git add the doc."
            +" Use the gotdocs-update skill. Never stamp verify without reading the change.")
    if decisions:
        parts.append("gotdocs: an architecture decision record governs this file: "+"; ".join(decisions)
            +". Run bin/gotdocs why --path "+rel+" before changing behavior here."
            +" If your change contradicts an accepted decision, say so and propose superseding it;"
            +" do not quietly rewrite the record to match the new code.")
    print(json.dumps({"hookSpecificOutput":{"hookEventName":"PostToolUse","additionalContext":" ".join(parts)}}))
except Exception:
    pass
' 2>/dev/null
exit 0
